code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A straight 5-bar carries a small color tile at one end; repeat it
    # along the bar, on the side where the tile is attached.
    lines = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            if c - a >= 2:
                lines.append(("H", r, a, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            if r - a >= 2:
                lines.append(("V", c, a, r - 1))

    for orient, fixed, lo, hi in lines:
        best = None
        if orient == "V":
            # Pick the colored rectangle to the left/right of an endpoint.
            for end in (lo, hi):
                for dc in (-1, 1):
                    c0 = fixed + dc
                    if not (0 <= c0 < w):
                        continue
                    step = 1 if end == lo else -1
                    seed_rows = []
                    rr = end
                    while lo <= rr <= hi and g[rr][c0] not in (0, 5):
                        seed_rows.append(rr)
                        rr += step
                    if not seed_rows:
                        continue
                    widths = []
                    for rr in seed_rows:
                        n = 0
                        cc = c0
                        while 0 <= cc < w and g[rr][cc] not in (0, 5):
                            n += 1
                            cc += dc
                        widths.append(n)
                    tw = min(widths)
                    tile = [[g[rr][c0 + dc*j] for j in range(tw)] for rr in seed_rows]
                    # Seed rows are ordered from the endpoint inward; normalize to top-down.
                    if step < 0:
                        tile.reverse()
                    cand = (len(seed_rows) * tw, len(seed_rows), tw, dc, end, tile)
                    if best is None or cand[0] > best[0]:
                        best = cand
            if best is not None:
                _, th, tw, dc, end, tile = best
                seed_top = end if end == lo else hi - th + 1
                for rr in range(lo, hi + 1):
                    tr = (rr - seed_top) % th
                    for j in range(tw):
                        cc = fixed + dc * (j + 1)
                        if 0 <= cc < w:
                            g[rr][cc] = tile[tr][j]
        else:
            # For a horizontal bar the sample is a color strip above/below
            # one endpoint; repeat that strip across the bar.
            for end in (lo, hi):
                for dr in (-1, 1):
                    r0 = fixed + dr
                    if not (0 <= r0 < h):
                        continue
                    step = 1 if dr == 1 else -1
                    vals = []
                    rr = r0
                    while 0 <= rr < h and g[rr][end] not in (0, 5):
                        vals.append(g[rr][end])
                        rr += step
                    if not vals:
                        continue
                    # Normalize to the natural outward order from the bar.
                    if dr == -1:
                        vals.reverse()
                    cand = (len(vals), end, dr, vals)
                    if best is None or cand[0] > best[0]:
                        best = cand
            if best is not None:
                _, end, dr, vals = best
                for cc in range(lo, hi + 1):
                    for j, value in enumerate(vals, start=1):
                        rr = fixed + dr * j
                        if 0 <= rr < h:
                            g[rr][cc] = value
    return g
'''
